INSERT INTO public.exercises (name, muscle_group, primary_muscle, description, technique, tips) VALUES
('Press de banca con barra','Pecho','Pectoral mayor','Empuje horizontal básico para pecho.','Escápulas retraídas, barra a la línea del pezón, codos a 45 grados.','Mantén los pies firmes en el suelo.'),
('Press inclinado con mancuernas','Pecho','Pectoral superior','Empuje inclinado a 30 grados.','Baja controlado hasta la altura del pecho.','No choques las mancuernas arriba.'),
('Dominadas','Espalda','Dorsal ancho','Tracción vertical con peso corporal.','Agarre prono, pecho al alto, hombros abajo.','Usa banda elástica si aún no llegas.'),
('Remo con barra','Espalda','Dorsal ancho','Tracción horizontal con tronco inclinado.','Espalda neutra, barra al ombligo.','Evita impulsar con la cadera.'),
('Sentadilla trasera','Piernas','Cuádriceps','Patrón de sentadilla con barra alta.','Rodillas en línea con los pies, baja hasta paralelo.','Mantén el core activo todo el recorrido.'),
('Peso muerto rumano','Piernas','Isquiotibiales','Bisagra de cadera con recorrido corto.','Cadera atrás, barra pegada a la pierna.','Para cuando notes tope en el isquio.'),
('Prensa de piernas','Piernas','Cuádriceps','Empuje de piernas en máquina.','Pies a la anchura de los hombros, no bloquees rodillas.','Controla la fase excéntrica.'),
('Press militar','Hombro','Deltoides anterior','Empuje vertical de pie.','Glúteo y abdomen apretados, barra sobre la cabeza.','No arquees la zona lumbar.'),
('Elevaciones laterales','Hombro','Deltoides medial','Aislamiento de deltoides lateral.','Codo ligeramente flexionado, sube hasta la altura del hombro.','Prioriza técnica sobre peso.'),
('Curl con barra','Brazo','Bíceps','Flexión de codo con barra recta.','Codos pegados al cuerpo, sin balanceo.','Aprieta arriba un segundo.'),
('Extensión de tríceps en polea','Brazo','Tríceps','Extensión de codo en polea alta.','Codos fijos, extiende completo.','Evita mover los hombros.'),
('Plancha abdominal','Core','Recto abdominal','Isométrico de core.','Cuerpo en línea recta, glúteo apretado.','Respira de forma constante.');